// === Tab: mySketch ===
let t = 0; // 時間の変数（アニメーションの進行）

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL); // ウィンドウ全体を使ってキャンバスを作成（WEBGLモード）
	background(155,0,0);
  noStroke(); // 線を描画しない設定
}

function draw() {
  clear(); // 背景をクリア
  t += 2; // 時間を進める

  let w = max(width, height); // キャンバスの短い方の長さを変数wに代入
  let count = int(w * 2 / 4); // オブジェクトの数を決定

  for (let i = 0; i < count; i++) { // オブジェクトの数だけ繰り返す
    let n = noise(i - t); // ノイズ値を取得（時間とインデックスに基づく）
    let d = n * PI * 4; // ノイズ値を角度に変換

    let x = cos(d) * i; // X座標を計算（円形に配置）
    let y = sin(d) * i; // Y座標を計算（円形に配置）

    push(); // 現在の描画スタイルと変換を保存
    let col = map(sin(d), -1, 1, 255, 0); // 色の値をsin波に基づいてマッピング
    fill(col,0,0); // 塗りの色を設定
    translate(x, y); // オブジェクトの位置を設定
    torus(w / 6, 10); // トーラスを描画（ドーナツ型の形）
    pop(); // 保存したスタイルと変換を復元
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight); // ウィンドウサイズ変更時にキャンバスをリサイズ
}


